package com.lmspilot.grading.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="grade_revisions",indexes=@Index(name="idx_grade_revision_grade",columnList="grade_id,created_at"))public class GradeRevisionEntity{@Id private UUID id=UUID.randomUUID();@Column(name="grade_id",nullable=false)private UUID gradeId;@Column(name="previous_score",nullable=false)private double previousScore;@Column(name="new_score",nullable=false)private double newScore;@Column(name="previous_percentage",nullable=false)private double previousPercentage;@Column(name="new_percentage",nullable=false)private double newPercentage;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private GradeRevisionType type;@Column(nullable=false,columnDefinition="text")private String reason;@Column(name="changed_by",nullable=false)private UUID changedBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();public GradeRevisionEntity(){}public GradeRevisionEntity(UUID g,double ps,double ns,double pp,double np,GradeRevisionType t,String r,UUID by){gradeId=g;previousScore=ps;newScore=ns;previousPercentage=pp;newPercentage=np;type=t;reason=r;changedBy=by;}public UUID getId(){return id;}public UUID getGradeId(){return gradeId;}public double getPreviousScore(){return previousScore;}public double getNewScore(){return newScore;}public double getPreviousPercentage(){return previousPercentage;}public double getNewPercentage(){return newPercentage;}public GradeRevisionType getType(){return type;}public String getReason(){return reason;}public UUID getChangedBy(){return changedBy;}public Instant getCreatedAt(){return createdAt;}}
